from django.contrib.auth.management import create_permissions
from django.db import migrations

MODELES = ('categorie', 'formation', 'moduleprogramme', 'documentformation')

# Droits sur le catalogue par rôle :
# - Administrateur : tous les droits, y compris la suppression ;
# - Gestionnaire : consultation, ajout et modification, sans suppression.
DROITS_PAR_GROUPE = {
    'Administrateur': ('view', 'add', 'change', 'delete'),
    'Gestionnaire': ('view', 'add', 'change'),
}


def attribuer_permissions(apps, schema_editor):
    # Les permissions ne sont normalement créées qu'après toutes les migrations (signal post_migrate) :
    # on les crée ici explicitement pour pouvoir les attribuer dès maintenant.
    app_config = apps.get_app_config('catalog')
    app_config.models_module = True
    create_permissions(app_config, apps=apps, verbosity=0)
    app_config.models_module = None

    Group = apps.get_model('auth', 'Group')
    Permission = apps.get_model('auth', 'Permission')
    for nom_groupe, actions in DROITS_PAR_GROUPE.items():
        groupe, _ = Group.objects.get_or_create(name=nom_groupe)
        codenames = [f'{action}_{modele}' for action in actions for modele in MODELES]
        groupe.permissions.add(*Permission.objects.filter(content_type__app_label='catalog', codename__in=codenames))


def retirer_permissions(apps, schema_editor):
    Group = apps.get_model('auth', 'Group')
    Permission = apps.get_model('auth', 'Permission')
    permissions = Permission.objects.filter(content_type__app_label='catalog')
    for groupe in Group.objects.filter(name__in=DROITS_PAR_GROUPE):
        groupe.permissions.remove(*permissions)


class Migration(migrations.Migration):

    dependencies = [
        ('catalog', '0001_initial'),
        ('accounts', '0002_creer_groupes_roles'),
        ('contenttypes', '0002_remove_content_type_name'),
    ]

    operations = [
        migrations.RunPython(attribuer_permissions, retirer_permissions),
    ]
